package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextToken()
 * Designed to maximize branch and line coverage.
 */
public class ReaderBasedJsonParser_nextToken_TriageGen1Test {

    private ReaderBasedJsonParser createParser(String json) throws IOException {
        return new ReaderBasedJsonParser(
                IOContext.Empty.instance,
                0,
                new StringReader(json),
                null,
                null,
                null,
                0,
                0,
                false
        );
    }

    @Test
    public void testNextToken_EndOfString() throws IOException {
        ReaderBasedJsonParser parser = createParser("");
        // The first call to nextToken on empty input should return null (end of input)
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_SimpleValueTypes() throws IOException {
        // Test Null
        ReaderBasedJsonParser parserNull = createParser("null");
        assertEquals(JsonToken.VALUE_NULL, parserNull.nextToken());
        assertNull(parserNull.nextToken());

        // Test True
        ReaderBasedJsonParser parserTrue = createParser("true");
        assertEquals(JsonToken.VALUE_TRUE, parserTrue.nextToken());
        assertNull(parserTrue.nextToken());

        // Test False
        ReaderBasedJsonParser parserFalse = createParser("false");
        assertEquals(JsonToken.VALUE_FALSE, parserFalse.nextToken());
        assertNull(parserFalse.nextToken());
    }

    @Test
    public void testNextToken_Numbers() throws IOException {
        // Positive number
        ReaderBasedJsonParser parserPos = createParser("123");
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserPos.nextToken());

        // Negative number
        ReaderBasedJsonParser parserNeg = createParser("-456");
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserNeg.nextToken());
    }

    @Test
    public void testNextToken_StringsAndArrays() throws IOException {
        // String
        ReaderBasedJsonParser parserStr = createParser("\"hello\"");
        assertEquals(JsonToken.VALUE_STRING, parserStr.nextToken());

        // Array
        ReaderBasedJsonParser parserArr = createParser("[1, 2]");
        assertEquals(JsonToken.START_ARRAY, parserArr.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parserArr.nextToken());
        assertEquals(JsonToken.END_ARRAY, parserArr.nextToken());
    }

    @Test
    public void testNextToken_Objects() throws IOException {
        // Object structure: {"key":"value"}
        ReaderBasedJsonParser parser = createParser("{\"key\":\"value\"}");

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("key", parser.getCurrentName());

        // This triggers the "if (_currToken == JsonToken.FIELD_NAME) return _nextAfterName();" branch
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_MismatchedEndArray() throws IOException {
        // Testing the branch: if (i == INT_RCURLY) { if (!_parsingContext.inArray()) ... }
        // We provide a '}' when the context is not an array.
        ReaderBasedJsonParser parser = createParser("}");
        try {
            parser.nextToken();
            fail("Should have thrown a JsonParseException due to mismatched end marker");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextToken_MismatchedEndObject() throws IOException {
        // Testing the branch: if (i == INT_RBRACKET) { if (!_parsingContext.inObject()) ... }
        ReaderBasedJsonParser parser = createParser("]");
        try {
            parser.nextToken();
            fail("Should have thrown a JsonParseException due to mismatched end marker");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextToken_UnexpectedChar() throws IOException {
        // Testing the branch: case ']': case '}': _reportUnexpectedChar(...)
        // This happens if a closer appears where a value is expected (e.g., after start object but no name)
        ReaderBasedJsonParser parser = createParser("{]");
        parser.nextToken(); // START_OBJECT
        try {
            parser.nextToken(); // Should fail because ']' is not a valid value start here
            fail("Should have thrown an exception");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextToken_IncompleteString() throws IOException {
        // Testing the branch: if (_tokenIncomplete) { _skipString(); }
        // This requires a parser state where _tokenIncomplete is true.
        // Since we can't easily manipulate internal state without reflection, 
        // we rely on the fact that the code path is exercised by the switch case '"'
        ReaderBasedJsonParser parser = createParser("\"incomplete");
        // The parser logic for string will set _tokenIncomplete = true.
        // To fully test the 'if (_tokenIncomplete)' branch, one would usually need 
        // a partial buffer scenario which is internal to Jackson's byte/char processing.
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextToken_OddValue() throws IOException {
        // Test the default case in switch: _handleOddValue(i)
        // Using a character like '?' which is not handled by specific cases
        ReaderBasedJsonParser parser = createParser("?");
        try {
            parser.nextToken();
        } catch (IOException e) {
            // Expected - handleOddValue will likely throw an exception or return unexpected token
        }
    }

    @Test
    public void testNextToken_CommaHandling() throws IOException {
        // Test the branch: if (_parsingContext.expectComma()) { i = _skipComma(i); }
        ReaderBasedJsonParser parser = createParser("[1,2]");
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }
}
